import{_ as a,o as t,c as i,a5 as r}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"PostgreSQL demo seed integrity","description":"","frontmatter":{},"headers":[],"relativePath":"feature/system-maintenance/postgres-demo-seed-integrity/spec.md","filePath":"feature/system-maintenance/postgres-demo-seed-integrity/spec.md"}'),s={name:"feature/system-maintenance/postgres-demo-seed-integrity/spec.md"};function n(o,e,d,c,l,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="postgresql-demo-seed-integrity" tabindex="-1">PostgreSQL demo seed integrity <a class="header-anchor" href="#postgresql-demo-seed-integrity" aria-label="Permalink to &quot;PostgreSQL demo seed integrity&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Repair the four reviewed defects in the explicit PostgreSQL demo dataset without changing existing databases.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Only approved package agreements produce campaigns. Agreements contain valid package terms; campaigns retain the agreed snapshot, version, deliverables and allocations, initially in DRAFT.</li><li>A database failure during flush or commit rolls back demo rows and leaves a durable failed seed marker. Successful data and the complete marker commit together; completed runs skip.</li><li>The reserved quick-login Client has a CLIENT membership in each of the first two demo workspaces, independently of legacy user numbers and input ordering.</li><li>Seeded ACTIVE subscriptions have an end date in the future; elapsed periods use EXPIRED.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Seed entrypoints and their persisted outputs are the regression boundaries identified in the review and accepted by the request to resolve all four defects. No schema migration, deletion, automatic repair of existing datasets, API or UI changes. Keep dataset version 2: marked completed databases remain untouched.</p><h2 id="definition-of-done" tabindex="-1">Definition of done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of done&quot;">​</a></h2><p>Regression checks cover these behaviors, including a real PostgreSQL deferred commit failure in an isolated database. Existing seed tests pass; document any unrelated suite failures.</p>',9)])])}const u=a(s,[["render",n]]);export{h as __pageData,u as default};
